import{at as e,it as t,n,vt as r}from"./chunks/framework.BtDTgfNe.js";var i=JSON.parse(`{"title":"String Literals - v5","description":"Learn about string literals in Textwire","frontmatter":{"title":"String Literals - v5","description":"Learn about string literals in Textwire"},"headers":[],"relativePath":"v5/language-elements/literals/string.md","filePath":"archive/v5/language-elements/literals/string.md","lastUpdated":1795438701000}`),a={name:`v5/language-elements/literals/string.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="string-literals" tabindex="-1">String Literals <a class="header-anchor" href="#string-literals" aria-label="Permalink to “String Literals”">​</a></h1><p>You can use string literals and concatenate them with other strings. You can use double or single quotes for strings. Example:</p><div class="language-textwire" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">textwire</span><pre class="shiki shiki-themes github-light catppuccin-mocha" style="--shiki-light:#24292e;--shiki-dark:#cdd6f4;--shiki-light-bg:#fff;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-style:inherit;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">{{</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;"> &quot;Hello&quot;</span><span style="--shiki-light:#c62739;--shiki-dark:#CBA6F7;"> + </span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;">&#39;World!&#39;</span><span style="--shiki-light:#005CC5;--shiki-light-font-style:inherit;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> }}</span></span></code></pre></div><p>When you print a string, it will be automatically escaped. If you want to print a string without escaping it, you can use the raw embedding with <code>{!!</code> and <code>!!}</code>. Example:</p><div class="language-textwire" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">textwire</span><pre class="shiki shiki-themes github-light catppuccin-mocha" style="--shiki-light:#24292e;--shiki-dark:#cdd6f4;--shiki-light-bg:#fff;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-light-font-style:inherit;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">{!!</span><span style="--shiki-light:#032F62;--shiki-dark:#A6E3A1;"> &quot;&lt;h1&gt;Test&lt;/h1&gt;&quot;</span><span style="--shiki-light:#005CC5;--shiki-light-font-style:inherit;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> !!}</span></span></code></pre></div><h2 id="auto-escaped-on-output" tabindex="-1">Auto-escaped on output <a class="header-anchor" href="#auto-escaped-on-output" aria-label="Permalink to “Auto-escaped on output”">​</a></h2><p>All strings are automatically HTML-escaped when printed to prevent XSS attacks.</p><h2 id="use-for-unescaped-output" tabindex="-1">Use <code>{!! !!}</code> for unescaped output <a class="header-anchor" href="#use-for-unescaped-output" aria-label="Permalink to “Use {!! !!} for unescaped output”">​</a></h2><p>Use the <code>{!! myVar !!}</code> when you need to output HTML, XML, JSON without escaping.</p><h2 id="concatenation-with" tabindex="-1">Concatenation with <code>+</code> <a class="header-anchor" href="#concatenation-with" aria-label="Permalink to “Concatenation with +”">​</a></h2><p>Use the <code>+</code> operator to join strings together.</p><h2 id="quote-flexibility" tabindex="-1">Quote flexibility <a class="header-anchor" href="#quote-flexibility" aria-label="Permalink to “Quote flexibility”">​</a></h2><p>Single and double quotes are interchangeable for string literals.</p><h2 id="escaping" tabindex="-1">Escaping <a class="header-anchor" href="#escaping" aria-label="Permalink to “Escaping”">​</a></h2><p>Use a backslash to insert special characters inside strings. See <a href="/v5/language-elements/syntax#escaping-in-strings">Escaping</a>.</p>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};